<script setup lang="ts">import{ref}from'vue';import{useAuth}from'../stores/auth';import{api}from'../api/client';const auth=useAuth(),form=ref({current_password:'',new_password:''}),message=ref('');async function change(){await api.post('/me/password',form.value);message.value='密码已修改，请重新登录';setTimeout(()=>auth.logout(),800)}</script>
<template><div class="page"><div class="page-title"><div><h1>个人资料</h1><p>查看当前账号角色、权限并修改登录密码</p></div></div><div class="stat-grid"><div class="stat-card"><span>用户名</span><strong>{{auth.user?.username}}</strong></div><div class="stat-card"><span>显示名称</span><strong>{{auth.user?.display_name||'-'}}</strong></div><div class="stat-card"><span>权限数量</span><strong>{{auth.permissions.length}}</strong></div></div><section class="card"><div class="form-grid"><label><span>原密码</span><input v-model="form.current_password" type="password"></label><label><span>新密码</span><input v-model="form.new_password" type="password"></label></div><div class="modal-footer"><span>{{message}}</span><button class="primary-button" @click="change">修改密码</button></div></section></div></template>
